 "content": "def transform(grid):
    """Connect axis-aligned hollow diamond motifs with color 1."""
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r - 1][c] == 2 and grid[r + 1][c] == 2
                    and grid[r][c - 1] == 2 and grid[r][c + 1] == 2):
                centers.append((r, c))

    out = [row[:] for row in grid]
    for i, (r1, c1) in enumerate(centers):
        for r2, c2 in centers[i + 1:]:
            if r1 == r2:
                lo, hi = sorted((c1, c2))
                # Fill the zero cells between the inward-facing horizontal tips.
                for c in range(lo + 2, hi - 1):
                    if out[r1][c] == 0:
                        out[r1][c] = 1
            elif c1 == c2:
